const D = { energy: .55, scale: 1, density: .55, speed: 1, surf: .6, haze: .55, hue: 150, x: .38, y: .5, style: 'headland', act: 'calm', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 150;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NC = 5;                                    // headland ranks, 0 = farthest

const STY = {
  // overcast coastal: grey-green grass-topped cliffs, cold slate sea
  headland: { skT:[205,20,66], skB:[190,14,82], hazeC:[190,16,74], rock:[145,22,30], rockL:[120,26,50],
              grass:[95,34,40], sea:[200,34,26], foam:[190,8,94], grain:20 },
  // low gold-hour sun: warm cliff faces, glittering water
  goldhour: { skT:[32,40,58], skB:[42,52,86], hazeC:[40,40,72], rock:[24,44,32], rockL:[38,56,58],
              grass:[54,48,44], sea:[36,30,44], foam:[46,16,96], grain:22 },
  // moonlit nocturne: blue-silver, near-monochrome
  nocturne: { skT:[228,42,14], skB:[214,30,34], hazeC:[214,24,40], rock:[220,28,16], rockL:[208,22,36],
              grass:[210,24,22], sea:[220,40,14], foam:[206,12,78], grain:14 },
  // ABSTRACTED sumi ink-wash: silhouette ranks in tonal washes
  ink:      { skT:[30,5,90], skB:[30,3,84], hazeC:[30,3,86], rock:[30,7,24], rockL:[30,5,44],
              grass:[30,8,34], sea:[30,4,70], foam:[30,2,92], grain:30 },
  // ABSTRACTED nautical chart: cyan, contour soundings, no photo shading
  chart:    { skT:[195,30,86], skB:[190,22,92], hazeC:[190,18,88], rock:[38,30,80], rockL:[42,26,90],
              grass:[70,26,74], sea:[196,44,72], foam:[200,30,96], grain:6 }
};
const st = STY[P.style] || STY.headland;

const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const wy = height * P.y;                          // sea horizon
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3) + '|' + P.x.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.caps.forEach(c => c.g.remove()); S.cloud.remove(); }
  S.sky = mk(W, H); S.cloud = mk(W, Math.max(2, wy + u * .05));

  // sky gradient
  const g = S.sky; g.noStroke();
  const cT = sh(st.skT), cB = sh(st.skB);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cB, Math.pow(Math.min(1, yy / Math.max(1, wy)), .7)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const hazeC = sh(st.hazeC), rockC = sh(st.rock), rockL = sh(st.rockL), grassC = sh(st.grass), foamC = sh(st.foam);
  const lit = P.x;

  // --- headland ranks: nearer = taller, lower base, darker, less haze ---
  S.caps = [];
  for (let L = 0; L < NC; L++) {
    const near = L / (NC - 1);
    const haze = (1 - near) * (.5 + .45 * hz);
    const side = (L % 2 === 0) ? -1 : 1;          // alternate which edge the cape enters from
    const q = mk(W, H); q.noStroke();
    const baseY = wy + u * (.02 + near * .14);     // where the cliff foot meets the sea
    const extent = W * (.28 + near * .34 + fr(L * 9 + 3) * .12);   // how far the cape reaches inward
    const crestY = wy - u * (.06 + near * .5 + fr(L * 9 + 5) * .18) * P.scale;
    const baseRock = L3(rockC, hazeC, haze);
    const baseLit = L3(rockL, hazeC, haze * .8);
    const xEdge = side < 0 ? extent : W - extent;  // the seaward cliff edge (vanishing point side)
    const xIn = side < 0 ? -u * .05 : W + u * .05;
    // crest profile from the inner edge to the seaward edge
    const crest = f => {
      const n = Math.sin(f * 6.3 + fr(L) * 6.3) * .5 + Math.sin(f * 13 + fr(L * 2) * 6.3) * .3 + Math.sin(f * 27) * .2;
      return crestY + n * u * (.03 + .05 * near) * P.scale - f * u * (.04 * near);
    };
    q.fill(baseRock[0], baseRock[1], baseRock[2], 100);
    q.beginShape();
    q.vertex(xIn, H);
    const steps = 40;
    for (let s = 0; s <= steps; s++) { const f = s / steps; q.vertex(xIn + (xEdge - xIn) * f, crest(f)); }
    // the seaward cliff face drops from crest to baseY
    q.vertex(xEdge, baseY);
    q.vertex(xIn, baseY);
    q.endShape(q.CLOSE);

    // strata / face texture on the seaward drop
    if (P.style === 'chart') {
      // contour soundings: horizontal ticks
      q.stroke(baseLit[0], baseLit[1], baseLit[2], 60); q.strokeWeight(1);
      for (let b = 0; b < 6; b++) { const yy = crestY + (baseY - crestY) * (b / 6); q.line(Math.min(xIn, xEdge), yy, Math.max(xIn, xEdge), yy); }
      q.noStroke();
    } else {
      const nb = Math.floor(8 + near * 10);
      for (let b = 0; b < nb; b++) {
        const f = b / nb;
        const yy = crestY + (baseY - crestY) * f;
        const shade = (side < 0) === (lit < .5) ? baseLit : L3(baseRock, [0,0,0], .35);
        q.strokeWeight(Math.max(.6, u * .0018 * (.4 + near))); q.stroke(shade[0], shade[1], Math.max(2, shade[2] + (fr(b) - .5) * 14), 30 + 26 * near);
        q.beginShape();
        for (let sx = Math.min(xIn, xEdge); sx <= Math.max(xIn, xEdge); sx += u * .03)
          q.vertex(sx, yy + Math.sin(sx * .01 + b) * u * .006 * P.scale);
        q.endShape();
      }
      // grass / vegetation fringe along the crest
      q.noFill(); q.strokeWeight(Math.max(.8, u * .003 * (.4 + near)));
      q.stroke(grassC[0], grassC[1], Math.min(70, grassC[2] + haze * 20), 70);
      q.beginShape();
      for (let s = 0; s <= steps; s++) { const f = s / steps; q.vertex(xIn + (xEdge - xIn) * f, crest(f) - u * .004); }
      q.endShape(); q.noStroke();
      // lit sunward edge of the seaward face
      q.fill(baseLit[0], baseLit[1] * .7, Math.min(99, baseLit[2] + 8), (26 + 26 * near) * en);
      q.rect(xEdge - (side < 0 ? u * .01 : 0), crestY, u * .012, baseY - crestY);
    }
    // aerial veil
    q.fill(hazeC[0], hazeC[1] * .8, hazeC[2], haze * 55);
    q.rect(0, 0, W, H);
    S.caps.push({ g: q, near: near, xEdge: xEdge, baseY: baseY, side: side });
  }

  // a drifting cloud band along the sky (tileable)
  const clC = L3(sh(st.hazeC), sh(st.skB), .3);
  S.cloud.noStroke();
  for (let i = 0; i < 10; i++) {
    const bx = fr(i * 5 + 41) * W, by = u * (.05 + fr(i * 5 + 42) * .4);
    const bw = u * (.5 + fr(i * 5 + 43) * 1), bhh = u * (.04 + fr(i * 5 + 44) * .08);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.cloud.fill(clC[0], clC[1] * (1 - kk * .12), Math.min(99, clC[2] + kk * 3), 8 * (1 - kk * .2));
      S.cloud.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { calm: { surf: 1, haze: 1, cloud: 1 }, swell: { surf: 1.5 + .1 * sec, haze: 1, cloud: 1.1 }, fog: { surf: .9, haze: 1 + sec * .1, cloud: 1.3 } };
const act = ACT[P.act] || ACT.calm;
const swell = P.surf * act.surf * (.7 + .3 * Math.sin(K.t * .23)) + A.bass * .3;

noStroke();
image(S.sky, 0, 0);

// cloud band
const CW = S.cloud.width;
const cx = ((-K.t * u * .006 * P.speed % CW) + CW) % CW;
push(); tint(0, 0, 100, 70 * act.cloud); image(S.cloud, cx - CW, 0); image(S.cloud, cx, 0); pop();

// ---------------- the sea ----------------
const seaC = sh(st.sea), foamC = sh(st.foam);
fill(seaC[0], seaC[1], seaC[2]); rect(0, wy, width, height - wy);
const nsw = Math.floor(18 + P.density * 20);
noFill();
for (let i = 0; i < nsw; i++) {
  const f = Math.pow((i + .5) / nsw, 1.8);
  const yy = wy + f * (height - wy);
  const d = Math.max(.04, f);
  const ph = K.t * (.3 + d * .55) * P.speed;
  strokeWeight(Math.max(.5, u * .0015 * (.3 + d * 2)));
  stroke(seaC[0], seaC[1] * .7, Math.min(99, seaC[2] + 12 + 16 * d), 24 + 30 * d);
  beginShape();
  for (let x = -10; x <= width + 10; x += Math.max(8, 18 * d)) {
    const w1 = Math.sin(x * .008 / (1 + d) + ph) * .7 + Math.sin(x * .02 - ph * 1.43 + i) * .3 + Math.sin(x * .0033 + K.t * .21) * .5;
    vertex(x, yy + w1 * u * .006 * d * (.5 + en));
  }
  endShape();
}
noStroke();

// ---------------- the headland ranks, farthest first, drifting subtly ----------------
const drift = 0.9 * Math.sin(K.t * .19) + 0.5 * Math.sin(K.t * .47 + 1.7) + 0.3 * Math.sin(K.t * .91);
for (let L = 0; L < NC; L++) {
  const c = S.caps[L];
  const dx = (drift * .4 + Math.sin(K.t * (.02 + L * .006) + L)) * u * .003 * (.3 + c.near);
  image(c.g, dx, Math.sin(K.t * (.017 + L * .004) + L * 2) * u * .0008);
  // ---- foam / surf at the foot of each seaward cliff ----
  if (P.style !== 'chart') {
    const fx = c.xEdge + dx, fyy = c.baseY;
    const nf = Math.floor((5 + P.density * 8) * (.3 + swell));
    for (let i = 0; i < nf; i++) {
      const life = ((K.t * (.25 + fr(i * 3 + L * 11 + 51) * .4) * P.speed + fr(i * 3 + L * 11 + 52)) % 1);
      const pulse = Math.max(0, Math.sin(life * 3.14159));
      const fw = u * (.02 + fr(i * 3 + 53) * .04) * (.4 + c.near) * P.scale * (.5 + swell);
      fill(foamC[0], foamC[1] * .5, foamC[2], 60 * pulse * (.5 + en));
      ellipse(fx + (fr(i * 3 + 54) - .5) * fw * 3, fyy - pulse * u * .02 * (.5 + swell), fw, fw * (.3 + pulse * .3));
    }
  }
}

// spray haze along the near foreground (broad, carries motion)
if (P.style !== 'chart') {
  blendMode(SCREEN);
  const near = S.caps[NC - 1];
  for (let i = 0; i < 4; i++) {
    const sy = near.baseY - u * (.02 + i * .04);
    fill(foamC[0], foamC[1] * .4, foamC[2], (3 + 6 * swell * en) * (1 - i * .2));
    ellipse(near.xEdge + Math.sin(K.t * .2 + i) * u * .05, sy, u * (.5 + i * .3), u * (.05 + i * .04));
  }
  blendMode(BLEND);
}

// grain, vignette, alpha
if (st.grain > 6) {
  const ng = Math.floor(st.grain * 5);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 201) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 202) * height;
    fill(st.sea[0], st.sea[1] * .4, fr(i * 3 + 203) > .5 ? 92 : 6, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.sea)[0], st.sea[1], 6, 18 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.sea)[0], st.sea[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
